const grammarContext=[...(D.grammar.explanation_en?[{type:'text',text:D.grammar.explanation_en}]:[]),{type:'text',text:D.grammar.explanation_zh,className:'context-cn'},...D.grammar.examples.map(t=>({type:'block',text:t}))];appendQuestions('grammar-a','Grammar · Practice A','Read the grammar reminder and examples.','Grammar focus · '+D.grammar.title,grammarContext,D.grammar.controlled,D.answers.grammar_controlled);appendQuestions('grammar-b','Grammar · Practice B','Use the same grammar idea in everyday situations.','Grammar focus · '+D.grammar.title,grammarContext,D.grammar.ket_style,D.answers.grammar_ket_style);if(D.grammar.production?.length)addGroup('grammar-c','Grammar · Your turn',()=>D.grammar.production.forEach((prompt,i)=>addSlide('grammar-c','Grammar · Production',`Make it your own · ${i+1}` ,grammarContext,box=>{box.append(el('div',`Task ${i+1} of ${D.grammar.production.length}`,'question-index'),el('div',prompt,'qhead'));const ta=document.createElement('textarea');ta.className='free-response';ta.placeholder='Write your own answer here.';const key=`a2-day${D.day}-grammar-production-${i}`;ta.value=localStorage.getItem(key)||'';ta.oninput=()=>localStorage.setItem(key,ta.value);box.append(ta);const lab=el('label',undefined,'self-check'),check=document.createElement('input');check.type='checkbox';check.checked=localStorage.getItem(key+'-done')==='true';check.onchange=()=>localStorage.setItem(key+'-done',String(check.checked));lab.append(check,el('span','I tried this task'));box.append(lab)})));
const rd=D.readings;const readParts=[['part1','Reading Part 1',D.answers.reading_part1],['part2','Reading Part 2',D.answers.reading_part2],['part3','Reading Part 3',D.answers.reading_part3],['part4','Reading Part 4',D.answers.reading_part4],['part5','Reading Part 5',D.answers.reading_part5]];
for(const [key,label,answers] of readParts){const p=rd[key];if(!p)continue;const sharedAudio={type:'audio',src:(D.audio?.[key]||`../../audio/day${String(D.day).padStart(2,'0')}/${key}.mp3`).replace('../../','../'),label:key==='part4'||key==='part5'?'Listen after you try. You may replay the recording.':'Read and listen. You may replay the recording.',aria:`${label} shared audio`};
if(key==='part1'){const start=slides.length;p.questions.forEach((q,i)=>{const tx=p.texts[i],text=typeof tx==='string'?tx:(tx.text||tx.notice||JSON.stringify(tx));const title=typeof tx==='string'?`Notice ${i+1}`:(tx.label||`Text ${i+1}`);addSlide(`reading-${key}`,label,title,[{type:'text',text},{type:'text',text:p.instructions,className:'context-instructions'},sharedAudio],box=>{box.append(el('div',`Question ${i+1} of ${p.questions.length}`,'question-index'));box.append(questionCard(q,answers[i],`reading-${key}`))})});registerGroup(`reading-${key}`,label,start)}
else{let c=[];if(p.texts)c.push({type:'profiles',items:p.texts.map((x,i)=>({label:x.label||String.fromCharCode(65+i),text:typeof x==='string'?x:(x.text||x.notice||JSON.stringify(x))}))});if(p.text)c.push({type:'text',text:p.text});c.push(sharedAudio);appendQuestions(`reading-${key}`,label,p.instructions,`${label} · shared text`,c,p.questions,answers)}}
for(const [key,p] of Object.entries(D.listening?.parts||{})){const audio={type:'audio',src:(D.listening.audio?.[key]||`../../audio/day${String(D.day).padStart(2,'0')}/listening/${key}.mp3`).replace('../../','../'),label:'Listen twice. Replay this same recording while you work through its questions.',aria:`Listening ${key} shared audio`};appendQuestions(`listening-${key}`,`Listening ${key.replace('part','Part ')}`,p.format,`${p.title} · shared recording`,[{type:'text',text:p.instructions||'You hear each recording twice.',className:'context-instructions'},audio],p.questions,D.answers[`listening_${key}`])}
if(D.speaking?.prompts?.length)addGroup('speaking','Speaking',()=>D.speaking.prompts.forEach((prompt,i)=>addSlide('speaking','Speaking',`${i+1} · ${D.speaking.title}`,[{type:'text',text:D.speaking.instructions,className:'context-instructions'},...(D.conversation||[]).map(t=>({type:'block',title:t.speaker,text:t.line}))],box=>{box.append(el('div','Your turn','task-kicker'),el('h2',prompt));const ta=document.createElement('textarea');ta.className='free-response';ta.placeholder='Write or plan your answer here.';box.append(ta);const reveal=el('button','Show sample answer');reveal.type='button';const sample=el('div',D.speaking.model?.[i]||'','model-answer');reveal.onclick=()=>{sample.classList.toggle('show');reveal.textContent=sample.classList.contains('show')?'Hide sample answer':'Show sample answer'};box.append(reveal,sample)})));
