   const lab=el('label',undefined,'self-check'),check=document.createElement('input'),key=`a2-day${D.day}-news-${n.selected_date}-${n.title}-${step.key}`;check.type='checkbox';check.checked=localStorage.getItem(key)==='true';check.onchange=()=>localStorage.setItem(key,String(check.checked));lab.append(check,el('span','这一遍练习完成'));box.append(lab);
